provider_audit.model_content:
{
  "requirements": [
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S004",
        "start_ref": "C006-S003"
      },
      "text": "投标人应登陆项目电子化交易系统，进入“项目交易”-“附件资料”下载投标（响应）客户端，按照客户端操作要求编制投标文件。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S006",
        "start_ref": "C006-S005"
      },
      "text": "投标人完成投标文件编制后，应按照招标文件第一章明确的签章要求，使用投标人电子签章对投标文件进行签章。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S007",
        "start_ref": "C006-S007"
      },
      "text": "投标人采用联合体方式投标的，电子投标文件均需加盖投标人联合体各自单位的电子签章。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S008",
        "start_ref": "C006-S008"
      },
      "text": "投标人完成投标文件签章后，使用投标人数字证书(CA）对投标文件进行加密。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S010",
        "start_ref": "C006-S010"
      },
      "text": "投标人须携带加密投标文件的数字证书（CA）和密封的非加密电子投标文件参加开标会议。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S013",
        "start_ref": "C006-S012"
      },
      "text": "投标人还应制作纸质投标文件1份。纸质投标文件不得行间插字、涂改或增删，如有修改，必须由投标人法人代表或经其正式授权代表签名或盖单位公章。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S014",
        "start_ref": "C006-S014"
      },
      "text": "纸质投标文件应与电子投标文件一致。因纸质投标文件与电子投标文件内容不一致而导致的不利后果由投标人承担。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S016",
        "start_ref": "C006-S015"
      },
      "text": "纸质投标文件应由投标人法人代表或经其正式授权代表逐页签名或逐页盖单位公章。正式授权代表签字的，投标文件中需附有“法人代表授权书”。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S017",
        "start_ref": "C006-S017"
      },
      "text": "投标人采用联合体方式投标的，纸质投标文件需加盖投标人联合体各自单位公章。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S019",
        "start_ref": "C006-S018"
      },
      "text": "纸质投标文件应由投标人法人代表或经其正式授权代表逐页签名或逐页盖单位公章。正式授权代表签字的，投标文件中需附有“法定代表人授权书”。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S024",
        "start_ref": "C006-S020"
      },
      "text": "纸质投标文件中的盖章、公章仅指与投标人名称全称相一致的标准单位公章，而非投标专用章等其他非公章。如使用投标专用章，须提供特别说明函，明确该投标专用章作为投标文件的签章其效力等同于单位公章（该特别说明函须同时加盖投标人单位公章和投标人投标专用章）。“法定代表人授权书、法定代表人和被授权人身份证明”必须按招标文件要求加盖与投标人名称全称相一致的标准单位公章。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S029",
        "start_ref": "C006-S028"
      },
      "text": "外层信封应写明项目名称、项目编号、投标人名称、地址和邮政编码，并于袋口密封处加盖公章。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S030",
        "start_ref": "C006-S030"
      },
      "text": "外层信封应注明“请勿在202 年 月 日 时 00 分（开标时间）之前启封”的字样。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S031",
        "start_ref": "C006-S031"
      },
      "text": "外层包装没有按上述规定密封的纸质投标文件和非加密的电子版投标文件将会被拒绝。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S032",
        "start_ref": "C006-S032"
      },
      "text": "电报、电话、传真、邮件形式的纸质投标文件概不接受。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S033",
        "start_ref": "C006-S033"
      },
      "text": "未按照招标文件要求密封的，采购人、采购代理机构应当拒收。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S035",
        "start_ref": "C006-S035"
      },
      "text": "投标人未能按招标文件要求提供投标文件纸质版和电子版（包括线上加密和现场递交的非加密电子版）的，投标文件按无效投标处理。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S037",
        "start_ref": "C006-S036"
      },
      "text": "投标文件电子版未按要求加盖《关于供应商办理CA数字证书及电子签章的通知》中指定供应商签发的单位电子签章（如遇启用纸质投标文件时，纸质投标文件未按要求加盖公章）的，投标文件按无效投标处理。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S040",
        "start_ref": "C006-S040"
      },
      "text": "投标人应当在投标截止时间前，通过项目电子化交易系统上传提交加密的电子投标文件1份。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S042",
        "start_ref": "C006-S041"
      },
      "text": "投标截止时间后，投标人未成功通过项目电子化交易系统上传提交已加密的电子投标文件的，将视为未提交投标文件，采购代理机构不再接收其他任何形式的投标文件，供应商已递交的其他任何形式的投标文件视为无效提交。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S044",
        "start_ref": "C006-S043"
      },
      "text": "成功通过项目电子化交易系统上传提交电子加密投标文件是指在投标截止时间前，上传提交按照最终版本招标文件编制加密的投标文件，并获取相应的《投标（响应）文件签收回执单》。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S047",
        "start_ref": "C006-S046"
      },
      "text": "投标人授权代表现场递交文件及参加开标时，应须另行单独递交法定代表人授权书（无需密封，含法定代表人、被授权人身份证复印件）。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S049",
        "start_ref": "C006-S048"
      },
      "text": "投标人未递交法定代表人授权书、有效身份证复印件或法定代表人授权书未加盖单位公章的，其现场递交的投标文件将被拒绝。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S053",
        "start_ref": "C006-S052"
      },
      "text": "投标人成功通过项目电子化交易系统上传提交已加密的电子投标文件后，在投标文件提交截止时间前，须现场递交密封的存有非加密电子投标文件的移动存储介质1份。非加密电子投标文件应与加密电子投标文件一致。"
    },
    {
      "category": "implementation",
      "mandatory_observed": true,
      "requires_confirmation": false,
      "source_range": {
        "end_ref": "C006-S056",
        "start_ref": "C006-S055"
      },
      "text": "投标人成功通过项目电子化交易系统上传提交已加密的电子投标文件后，在投标文件提交截止时间前，须现场递交密封的纸质投标文件1份。纸质投标文件应与加密电子投标文件一致。"
    }
  ]
}

